// Changed representation: fixed-schema Rust unquote and inverse SimpleFold.
// Original Unicode15 tables.go marker (reference data, not a generated Rust file):
// Code generated by running "go generate" in golang.org/x/text. DO NOT EDIT.
// Original table Version = "15.0.0". See source-manifest.json and its notices.

fn hex4(input: &[u8]) -> Option<u16> {
    let mut value = 0;
    for &byte in input.get(..4)? {
        let digit = match byte {
            b'0'..=b'9' => byte - b'0',
            b'a'..=b'f' => byte - b'a' + 10,
            b'A'..=b'F' => byte - b'A' + 10,
            _ => return None,
        };
        value = (value << 4) | u16::from(digit);
    }
    Some(value)
}

/// Go DecodeRune consumes ONE byte on invalid UTF8, including an incomplete
/// multibyte sequence. Rust's lossy-string chunk replacement is not this rule.
fn rune(input: &[u8]) -> (char, usize) {
    let first = input[0];
    if first < 0x80 {
        return (char::from(first), 1);
    }
    let (width, minimum, maximum) = match first {
        0xc2..=0xdf => (2, 0x80, 0xbf),
        0xe0 => (3, 0xa0, 0xbf),
        0xe1..=0xec | 0xee..=0xef => (3, 0x80, 0xbf),
        0xed => (3, 0x80, 0x9f),
        0xf0 => (4, 0x90, 0xbf),
        0xf1..=0xf3 => (4, 0x80, 0xbf),
        0xf4 => (4, 0x80, 0x8f),
        _ => return (char::REPLACEMENT_CHARACTER, 1),
    };
    if input.len() < width
        || !(minimum..=maximum).contains(&input[1])
        || input[2..width].iter().any(|b| !(0x80..=0xbf).contains(b))
    {
        return (char::REPLACEMENT_CHARACTER, 1);
    }
    let mut value = u32::from(first & (0x7f >> width));
    for &byte in &input[1..width] {
        value = (value << 6) | u32::from(byte & 0x3f);
    }
    (
        char::from_u32(value).unwrap_or(char::REPLACEMENT_CHARACTER),
        width,
    )
}

/// Input is a complete quoted token validated by the private grammar scanner.
pub(super) fn unquote(token: &[u8]) -> String {
    let input = &token[1..token.len() - 1];
    let mut output = String::new();
    let mut pos = 0;
    while pos < input.len() {
        if input[pos] != b'\\' {
            let (ch, width) = rune(&input[pos..]);
            output.push(ch);
            pos += width;
            continue;
        }
        pos += 1;
        let escape = input[pos];
        pos += 1;
        if escape != b'u' {
            output.push(match escape {
                b'b' => '\u{08}',
                b'f' => '\u{0c}',
                b'n' => '\n',
                b'r' => '\r',
                b't' => '\t',
                _ => char::from(escape),
            });
            continue;
        }
        // Scanner validation establishes all four hex digits.
        let high = hex4(&input[pos..]).unwrap_or(0xfffd);
        pos += 4;
        let mut scalar = u32::from(high);
        if (0xd800..=0xdfff).contains(&high) {
            scalar = 0xfffd;
            if (0xd800..=0xdbff).contains(&high)
                && input[pos..].starts_with(b"\\u")
                && let Some(low) = hex4(&input[pos + 2..])
                && (0xdc00..=0xdfff).contains(&low)
            {
                scalar = 0x10000 + ((u32::from(high) - 0xd800) << 10) + u32::from(low) - 0xdc00;
                pos += 6;
            }
        }
        output.push(char::from_u32(scalar).unwrap_or(char::REPLACEMENT_CHARACTER));
    }
    output
}

/// Inverse Go Unicode15 SimpleFold for THESE ASCII schema names only. The
/// source caseOrbit/CaseRanges admit long-s into S's orbit. K's Kelvin orbit
/// cannot match any schema name; dotted/dotless I are singleton exceptions.
/// This is neither current Rust Unicode lowercasing nor search normalization.
pub(super) fn field<const N: usize>(key: &str, names: [&str; N]) -> Option<usize> {
    names.iter().position(|name| *name == key).or_else(|| {
        names.iter().position(|name| {
            let mut chars = key.chars();
            name.bytes().all(|byte| {
                chars.next().is_some_and(|ch| {
                    let folded = if ch == '\u{017f}' {
                        's'
                    } else {
                        ch.to_ascii_lowercase()
                    };
                    folded == char::from(byte.to_ascii_lowercase())
                })
            }) && chars.next().is_none()
        })
    })
}
